import{_ as t,o as a,c as o,a3 as i}from"./chunks/framework.DAK02U1-.js";const g=JSON.parse('{"title":"Patching and Upgrading LLVM","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Patching and Upgrading LLVM | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/dev/llvm-patches"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/dev/llvm-patches"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/dev/llvm-patches"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/dev/llvm-patches"}]]},"headers":[],"relativePath":"xclang/dev/llvm-patches.md","filePath":"en/xclang/dev/llvm-patches.md","lastUpdated":1791237348000}'),r={name:"xclang/dev/llvm-patches.md"};function l(n,e,s,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="patching-and-upgrading-llvm" tabindex="-1">Patching and Upgrading LLVM <a class="header-anchor" href="#patching-and-upgrading-llvm" aria-label="Permalink to &quot;Patching and Upgrading LLVM&quot;">​</a></h1><p>xclang builds LLVM&#39;s release source with the changes in <a href="https://github.com/clice-io/xclang/tree/main/patches" target="_blank" rel="noreferrer"><code>patches/</code></a>. The maintainers&#39; step lists are the llvm-patch and llvm-upgrade skills in <a href="https://github.com/clice-io/xclang/tree/main/.claude/skills" target="_blank" rel="noreferrer">.claude/skills</a>; this page is the same, for people. What each patch does is in <a href="./../reference/patches">LLVM patches</a>.</p><h2 id="the-rules-a-patch-follows" tabindex="-1">The Rules a Patch Follows <a class="header-anchor" href="#the-rules-a-patch-follows" aria-label="Permalink to &quot;The Rules a Patch Follows&quot;">​</a></h2><ul><li><strong>Applied without fuzz.</strong> <code>scripts/common.ts</code> applies every <code>patches/NNNN-name/*.patch</code> in directory order right after unpacking the source, with <code>patch -p1 -F0 --forward</code>: a patch applies where it was made or the build fails, so a tag&#39;s build is exactly its series.</li><li><strong>Upstream&#39;s fix when there is one</strong>, without its tests. A patch is a bridge to an LLVM release that has the fix, and is dropped then.</li><li><strong>A check that fails without it</strong>, in tests/smoke.ts (or the build system tests), run on every host.</li><li><strong>A README</strong> in the patch&#39;s directory: what goes wrong and who hit it, what the patch does, <code>Upstream:</code> (the issue, the PR, their state), <code>From:</code>, and <code>Checked:</code> (how it was verified, with run ids).</li><li><strong>Numbers are never reused</strong>: 0005, dropped in 23.1.2.5, stays gone.</li><li><code>*.patch</code> files are <code>-text</code> in <code>.gitattributes</code>: git does not convert their line endings, and an editor must not either.</li></ul><h2 id="adding-one" tabindex="-1">Adding One <a class="header-anchor" href="#adding-one" aria-label="Permalink to &quot;Adding One&quot;">​</a></h2><ol><li><code>patches/NNNN-short-name/</code> with <code>NNNN.patch</code> (against the release source, paths <code>a/…</code> and <code>b/…</code>, as <code>git diff</code> writes them) and <code>README.md</code>.</li><li>Check locally: <code>patch -p1 -F0 --dry-run -d &lt;llvm-project at llvmorg-&lt;version&gt;&gt; -i patches/NNNN-*/NNNN.patch</code>, and compile the patched file against the release&#39;s headers. Do not build LLVM locally.</li><li>Add the check to tests/smoke.ts, and confirm it on CI on an <code>exp/&lt;name&gt;</code> branch: a main.yml run with and without the patch, a toolchain without PGO for a quick A/B.</li><li>Docs: the table in <a href="./../reference/patches">LLVM patches</a>, and a CHANGELOG Unreleased entry.</li><li>Report or send it upstream when the maintainers agree to; record the link in its README.</li></ol><h2 id="upgrading-llvm" tabindex="-1">Upgrading LLVM <a class="header-anchor" href="#upgrading-llvm" aria-label="Permalink to &quot;Upgrading LLVM&quot;">​</a></h2><ol><li><code>LLVM_VERSION</code> and the sha256 of every pinned source in <code>scripts/common.ts</code>, from LLVM&#39;s release page.</li><li>Each patch: dropped if upstream took it, otherwise regenerated against the new source (<code>-F0</code>), keeping its number, with its README&#39;s <code>Checked:</code> updated.</li><li>Version-specific code: <code>grep -rn &quot;23\\b\\|23\\.1&quot;</code> over the TypeScript, Starlark, CMake and workflow files, and read each hit (tests/libclang.ts, the benchmark&#39;s compilers, renamed CMake options, the option tables&#39; paths, pgo/remap.txt, the Bazel module&#39;s library list).</li><li>The bootstrap: the previous xclang release, unless a major version needs a newer compiler; then LLVM&#39;s own release build, as for 23.1.2.1.</li><li>A full main.yml run on <code>exp/&lt;llvm version&gt;</code>; the training and the smoke tests are where a new version breaks most.</li><li>The first release of the new version is <code>&lt;version&gt;.1</code> (<a href="./releasing">releasing</a>).</li></ol>',8)])])}const m=t(r,[["render",l]]);export{g as __pageData,m as default};
